module benchmark/solution
import std/math (round, intToFloat)

export func main() -> () ! {IO} {
  let height_m = 1.75;
  let weight_kg = 70;
  let height_squared = height_m * height_m;
  let bmi_raw = intToFloat(weight_kg) / height_squared;
  let bmi_rounded = round(bmi_raw * 10.0) / 10.0;
  let category = if bmi_raw < 18.5 then "Underweight" else if bmi_raw < 25.0 then "Normal" else if bmi_raw < 30.0 then "Overweight" else "Obese";
  println("BMI=${show(bmi_rounded)} Category=${category}")
}
